static GUPRebateDateInstanceValue METFindByRebateDateRecId(RefRecId _rebateDateRecId, boolean _forupdate = false)
{
    GUPRebateDateInstanceValue gupRebateDateInstanceValue;

    gupRebateDateInstanceValue.selectForUpdate(_forupdate);
    select firstonly gupRebateDateInstanceValue
        where gupRebateDateInstanceValue.RebateDateRecId == _rebateDateRecId;

    return gupRebateDateInstanceValue;
}
